 static final BlockPos TREE=new BlockPos(180,-60,-8),BED=new BlockPos(207,-60,0),FIELD=new BlockPos(202,-61,10),TRAP=new BlockPos(202,-60,-7),DOOR=new BlockPos(210,-60,-7),OTHER_BED=new BlockPos(0,100,0),BIOME=new BlockPos(216,-60,24);
 static final Path OUT=Path.of(System.getProperty("kelmagic.qaOutput","qa-r10"));static boolean opened,requested,configured;static volatile boolean ready;static int wait,frame,stage=-1,checks;static String oldBiome;static final Map<BlockPos,String> oldCells=new LinkedHashMap<>();static int settle;static volatile boolean biomeChanged;
 static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError("R10 "+s);System.out.println("R10_PASS "+s);}
 static void server(java.util.function.Consumer<ServerPlayer> f){var m=Minecraft.getInstance();m.getSingleplayerServer().execute(()->{try{f.accept(m.getSingleplayerServer().getPlayerList().getPlayers().getFirst());}catch(Throwable e){e.printStackTrace();m.execute(()->{throw new RuntimeException(e);});}});}
 static void put(ServerLevel l,BlockPos p,BlockState s){l.setBlock(p,s,3);}
 static void clear(ServerLevel l,BlockPos a,BlockPos b){for(var p:BlockPos.betweenClosed(a,b))if(!l.getBlockState(p).isAir())put(l,p,Blocks.AIR.defaultBlockState());}
 static void bed(ServerLevel l,BlockPos foot,Direction d){put(l,foot.below(),Blocks.OBSIDIAN.defaultBlockState());put(l,foot.relative(d).below(),Blocks.OBSIDIAN.defaultBlockState());var s=MagicDreams.BED.get().defaultBlockState().setValue(BedBlock.FACING,d);l.setBlock(foot,s.setValue(BedBlock.PART,BedPart.FOOT),2);l.setBlock(foot.relative(d),s.setValue(BedBlock.PART,BedPart.HEAD),3);}
 static void camera(ServerPlayer p,Vec3 eye,Vec3 target){var delta=target.subtract(eye);float yaw=(float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),pitch=(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z)));p.getAbilities().flying=true;p.setNoGravity(true);p.onUpdateAbilities();p.connection.teleport(eye.x,eye.y-p.getEyeHeight(),eye.z,yaw,pitch);}
 static void room(ServerLevel l,BlockPos pos){for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)l.getChunk((pos.getX()>>4)+x,(pos.getZ()>>4)+z);clear(l,pos.offset(-6,0,-6),pos.offset(6,5,6));for(var p:BlockPos.betweenClosed(pos.offset(-6,-1,-6),pos.offset(6,-1,6)))put(l,p,Blocks.OBSIDIAN.defaultBlockState());}
 static void tests(ServerPlayer real){var l=real.serverLevel();real.gameMode.changeGameModeForPlayer(GameType.CREATIVE);real.teleportTo(l,211,-57,30,180,20);real.getInventory().clearContent();l.setDayTime(6000);l.setWeatherParameters(60000,0,false,false);
  for(int x=9;x<=15;x++)for(int z=-2;z<=3;z++)l.getChunk(x,z);
  var recipe=l.getRecipeManager().byKey(ResourceLocation.fromNamespaceAndPath("kelmagic","otherworld_dream_bed")).orElseThrow().value();var counts=new HashMap<Item,Integer>();for(var ing:recipe.getIngredients())if(!ing.isEmpty()){ok(ing.getItems().length==1,"bed ingredient is exact, not generic tag");counts.merge(ing.getItems()[0].getItem(),1,Integer::sum);}ok(counts.size()==3&&counts.get(MagicGrove.PLANKS.asItem())==2&&counts.get(MagicResonance.MANA_ITEM.get())==1&&counts.get(MagicMaterials.WOOL_ITEM.get())==3,"bed recipe exact 2 midnight planks + mana block + 3 golden wool");ok(recipe.getResultItem(l.registryAccess()).is(MagicDreams.BED_ITEM),"bed recipe produces new bed");
  for(var leaf:List.of(MagicGrove.LEAVES.get(),MagicGrove.GOLDEN_LEAVES.get())){int saplings=0;for(int i=0;i<2000;i++)for(var s:Block.getDrops(leaf.defaultBlockState(),l,TREE,null,real,ItemStack.EMPTY))if(s.is(MagicGrove.SAPLING.asItem()))saplings+=s.getCount();ok(saplings==0,"no saplings in leaf loot 2000 trials "+leaf);var drops=Block.getDrops(leaf.defaultBlockState(),l,TREE,null,real,Items.SHEARS.getDefaultInstance());ok(drops.stream().anyMatch(s->s.is(leaf.asItem())),"shears preserve "+leaf);}
  var tree=l.registryAccess().registryOrThrow(Registries.CONFIGURED_FEATURE).get(MagicGrove.TREE);ok(tree.feature() instanceof MidnightTreeFeature,"real custom tree feature, not jungle tree configuration");
  var trial=new BlockPos(160,-60,40);for(int seed=0;seed<6;seed++){clear(l,trial.offset(-12,0,-12),trial.offset(12,32,12));ok(tree.place(l,l.getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(seed),trial),"custom tree generated seed "+seed);int logs=0,leaves=0,gold=0;for(var p:BlockPos.betweenClosed(trial.offset(-12,0,-12),trial.offset(12,32,12))){var s=l.getBlockState(p);if(s.is(MagicGrove.LOG.get()))logs++;if(s.getBlock() instanceof LeavesBlock){leaves++;ok(s.getValue(LeavesBlock.DISTANCE)<=6,"natural leaf within supporting log distance");if(s.is(MagicGrove.GOLDEN_LEAVES.get()))gold++;}}ok(logs>=96,"tree logs >=96 seed "+seed+" logs="+logs);for(int x=-1;x<=2;x++)for(int z=-1;z<=2;z++)if((x==-1||x==2)^(z==-1||z==2))for(int y=0;y<2;y++)ok(l.getBlockState(trial.offset(x,y,z)).is(MagicGrove.LOG.get()),"buttress foot matches reference "+seed);System.out.println("R10_TREE seed="+seed+" logs="+logs+" leaves="+leaves+" gold="+gold);}
  clear(l,trial.offset(-12,0,-12),trial.offset(12,32,12));put(l,trial.offset(-1,0,0),Blocks.DIAMOND_BLOCK.defaultBlockState());ok(!tree.place(l,l.getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(4),trial),"blocked tree returns failure");ok(l.getBlockState(trial.offset(-1,0,0)).is(Blocks.DIAMOND_BLOCK),"blocked tree preserves building");ok(l.getBlockState(trial).isAir(),"tree preflight leaves no partial trunk");
  for(var dim:List.of(Level.OVERWORLD,Level.NETHER,Level.END)){var world=l.getServer().getLevel(dim);room(world,OTHER_BED);world.setDayTime(18000);world.updateSkyBrightness();var f=net.neoforged.neoforge.common.util.FakePlayerFactory.get(world,new com.mojang.authlib.GameProfile(UUID.nameUUIDFromBytes(dim.location().toString().getBytes()),"R10BedTest"));f.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);f.setHealth(20);f.setPos(2,100,1);bed(world,OTHER_BED,Direction.NORTH);var head=OTHER_BED.north();var result=world.getBlockState(OTHER_BED).useWithoutItem(world,f,new BlockHitResult(Vec3.atCenterOf(OTHER_BED),Direction.UP,OTHER_BED,false));ok(result.consumesAction(),"bed interaction "+dim.location());if(!f.isSleeping())System.out.println("R10_SLEEP_DIAG "+dim.location()+" direct="+f.startSleepInBed(head)+" state="+world.getBlockState(head)+" intact="+DreamBedBlock.intact(world,head)+" alive="+f.isAlive()+" night="+world.isNight());ok(f.isSleeping(),"actual server sleeping "+dim.location());ok(DreamBedBlock.intact(world,head),"bed has not exploded "+dim.location());ok(f.getRespawnDimension().equals(dim)&&head.equals(f.getRespawnPosition())&&!f.isRespawnForced(),"unforced spawn points to bed in "+dim.location());f.stopSleepInBed(true,true);var respawn=f.findRespawnPositionAndUseSpawnBlock(false,DimensionTransition.DO_NOTHING);ok(respawn.newLevel()==world&&!respawn.missingRespawnBlock()&&respawn.pos().distanceTo(Vec3.atCenterOf(head))<5,"authoritative respawn transition uses otherworld bed "+dim.location());
   var saved=new net.minecraft.nbt.CompoundTag();f.saveWithoutId(saved);var restored=new ServerPlayer(l.getServer(),l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"R10Restored"),ClientInformation.createDefault());restored.load(saved);ok(restored.getRespawnDimension().equals(dim)&&head.equals(restored.getRespawnPosition()),"player NBT restores otherworld spawn "+dim.location());
   f.setPos(40,100,40);var far=f.startSleepInBed(head);ok(far.left().orElse(null)==net.minecraft.world.entity.player.Player.BedSleepingProblem.TOO_FAR_AWAY,"bed rejects remote sleep "+dim.location());f.setPos(2,100,1);put(world,head.above(),Blocks.OBSIDIAN.defaultBlockState());ok(f.startSleepInBed(head).left().orElse(null)==net.minecraft.world.entity.player.Player.BedSleepingProblem.OBSTRUCTED,"bed rejects blocked head "+dim.location());put(world,head.above(),Blocks.AIR.defaultBlockState());
   for(var q:BlockPos.betweenClosed(head.offset(-4,0,-4),head.offset(4,4,4)))if(!q.equals(head)&&!q.equals(OTHER_BED))put(world,q,Blocks.OBSIDIAN.defaultBlockState());ok(MagicDreams.BED.get().getRespawnPosition(world.getBlockState(head),EntityType.PLAYER,world,head,0).isEmpty(),"fully enclosed bed has no safe respawn "+dim.location());room(world,OTHER_BED);bed(world,OTHER_BED,Direction.NORTH);put(world,head,Blocks.AIR.defaultBlockState());ok(MagicDreams.BED.get().getRespawnPosition(MagicDreams.BED.get().defaultBlockState().setValue(BedBlock.PART,BedPart.HEAD),EntityType.PLAYER,world,head,0).isEmpty(),"destroyed bed cannot keep spawn "+dim.location());
   for(var d:Direction.Plane.HORIZONTAL){bed(world,OTHER_BED,d);ok(DreamBedBlock.intact(world,OTHER_BED.relative(d)),"two-part bed facing "+d+" in "+dim.location());var items=world.getEntitiesOfClass(ItemEntity.class,new AABB(OTHER_BED).inflate(5));items.forEach(Entity::discard);f.gameMode.destroyBlock(OTHER_BED);int total=world.getEntitiesOfClass(ItemEntity.class,new AABB(OTHER_BED).inflate(5)).stream().filter(it->it.getItem().is(MagicDreams.BED_ITEM)).mapToInt(it->it.getItem().getCount()).sum();ok(total==1,"breaking either bed assembly yields one bed "+d+" in "+dim.location()+" got="+total);ok(world.getBlockState(OTHER_BED).isAir()&&world.getBlockState(OTHER_BED.relative(d)).isAir(),"breaking removes both halves "+d);}
   room(world,OTHER_BED);bed(world,OTHER_BED,Direction.NORTH);
  }
  l.setDayTime(6000);for(int n=-20;n<=20;n++){double x=n*.5,z=16;int a=MagicGrassRenderer.color(x,z,0),b=MagicGrassRenderer.color(x,z,125);ok(a!=b||a!=MagicGrassRenderer.color(x,z,73),"wave moves over time "+n);ok(a==MagicGrassRenderer.color(x,z,0),"wave shared exact world vertex "+n);}ok(MagicGrassRenderer.color(0,0,0)==MagicGrassRenderer.color(32,0,0),"wave continuous spatial period");ok(MagicGrassRenderer.color(0,0,0)==MagicGrassRenderer.color(0,0,500),"wave continuous time period");ok(!MagicDreams.GRASS.get().defaultBlockState().isRandomlyTicking(),"grass does not recolour by server random ticks");
  var wood=ResearchCatalog.BY_ID.get("midnight_wood");ok(MagicGrove.research("otherworld_dream_bed").equals(wood.id())&&MagicGrove.research("magic_grass_block").equals(wood.id()),"new crafts use existing wood discovery");for(var n:ResearchCatalog.NODES){ok(!n.example().matches("(?s).*[0-9%].*"),"no technical figures in ordinary codex "+n.id());ok(!n.example().contains("nov"),"no nov recolour hints in ordinary codex "+n.id());}ok(ResearchCatalog.BY_ID.get("magic_sapling").example().contains("бесплодные"),"barren forest lore present");
 }
 static void scene(ServerPlayer p){var l=p.serverLevel();clear(l,new BlockPos(166,-60,-22),new BlockPos(240,-20,40));for(var q:BlockPos.betweenClosed(new BlockPos(166,-61,-22),new BlockPos(240,-61,40)))put(l,q,Blocks.GRASS_BLOCK.defaultBlockState());var tree=l.registryAccess().registryOrThrow(Registries.CONFIGURED_FEATURE).get(MagicGrove.TREE);ok(tree.place(l,l.getChunkSource().getGenerator(),net.minecraft.util.RandomSource.create(42),TREE),"presentation tree grows from one planned origin");bed(l,BED,Direction.NORTH);for(var q:BlockPos.betweenClosed(FIELD,FIELD.offset(31,0,23)))put(l,q,MagicDreams.GRASS.get().defaultBlockState());
  for(int i=0;i<3;i++){var at=TRAP.east(i*3);put(l,at.below(),MagicGrove.PLANKS.get().defaultBlockState());put(l,at,MagicGrove.TRAPDOOR.get().defaultBlockState().setValue(TrapDoorBlock.FACING,Direction.NORTH).setValue(TrapDoorBlock.OPEN,i>0).setValue(TrapDoorBlock.HALF,i==2?Half.TOP:Half.BOTTOM));}
  for(int i=0;i<2;i++){var at=DOOR.east(i*3);var s=MagicGrove.DOOR.get().defaultBlockState().setValue(DoorBlock.FACING,Direction.SOUTH).setValue(DoorBlock.HINGE,i==0?DoorHingeSide.LEFT:DoorHingeSide.RIGHT);l.setBlock(at,s.setValue(DoorBlock.HALF,DoubleBlockHalf.LOWER),2);l.setBlock(at.above(),s.setValue(DoorBlock.HALF,DoubleBlockHalf.UPPER),3);}
  Research.save(p,ResearchState.EMPTY.add("learned","midnight_wood").add("learned","magic_sapling"));p.getInventory().setItem(0,MagicDreams.BED_ITEM.toStack());p.getInventory().setItem(1,MagicDreams.GRASS_ITEM.toStack());p.getInventory().setItem(2,MagicGrove.SAPLING.toStack());camera(p,new Vec3(208,-52,35),new Vec3(210,-60,15));
 }
 static void entry(String id,int spread){var m=Minecraft.getInstance();var parent=new CodexScreen(new CodexOpen(List.of(),List.of(),false,2,0,"","qa",0,true,false));var book=new ResearchEntryScreen(parent,ResearchCatalog.BY_ID.get(id));m.setScreen(book);if(spread>0)try{var f=ResearchEntryScreen.class.getDeclaredField("spread");f.setAccessible(true);f.setInt(book,spread);}catch(Exception e){throw new RuntimeException(e);}}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){if(!Boolean.getBoolean("kelmagic.r10QA"))return;var m=Minecraft.getInstance();if(m.getOverlay()!=null)return;if(m.level==null){if(!opened&&m.screen instanceof TitleScreen&&++wait>30){opened=true;m.createWorldOpenFlows().openWorld("KelMagicResearchR10QA",()->{});}return;}if(m.player==null||m.getSingleplayerServer()==null)return;
  if(!requested){requested=true;server(p->{tests(p);scene(p);ready=true;});return;}if(!ready)return;if(!configured){configured=true;m.options.enableVsync().set(false);m.options.framerateLimit().set(60);m.options.renderDistance().set(5);m.options.guiScale().set(2);m.options.languageCode="ru_ru";m.resizeDisplay();m.getToasts().clear();try{Files.createDirectories(OUT);}catch(Exception e){throw new RuntimeException(e);}}
  if(++settle<120)return;int s=frame/80,t=frame%80;if(s>=23){System.out.println("R10_NATIVE_COMPLETE checks="+checks);m.stop();return;}if(stage!=s){stage=s;m.options.hideGui=true;m.setScreen(null);
   if(s==0)server(p->camera(p,new Vec3(159,-42,23),new Vec3(181,-49,-7)));
   if(s==1)server(p->camera(p,new Vec3(175,-56,0),new Vec3(180.5,-58,-7.5)));
   if(s==2)server(p->camera(p,new Vec3(167,-32,12),new Vec3(180.5,-40,-7.5)));
   if(s==3)server(p->camera(p,new Vec3(204,-56,-1),new Vec3(205.5,-59,-7)));
   if(s==4)server(p->camera(p,new Vec3(212,-58.3,-2),new Vec3(212,-59,-6.6)));
   if(s==5)server(p->camera(p,new Vec3(212,-58.3,-12),new Vec3(212,-59,-6.6)));
   if(s==6)server(p->camera(p,new Vec3(214.5,-58.5,-6.5),new Vec3(210.8,-59,-6.5)));
   if(s==7)server(p->camera(p,new Vec3(212,-56,-7),new Vec3(211,-58,-6.5)));
   if(s==8||s==9)server(p->camera(p,new Vec3(216,-48,38),new Vec3(217,-60,21)));
   if(s==10)server(p->camera(p,new Vec3(210,-57,4),new Vec3(207.5,-59.4,-.5)));
   if(s==11){m.options.hideGui=false;m.setScreen(new net.minecraft.client.gui.screens.inventory.InventoryScreen(m.player));}
   if(s==12)entry("midnight_wood",0);
   if(s==13)entry("midnight_wood",2);
   if(s==14)entry("magic_sapling",0);
   if(s==15)server(p->{var nether=p.server.getLevel(Level.NETHER);p.teleportTo(nether,2,100,1,90,0);p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);p.setNoGravity(false);p.setHealth(20);nether.getBlockState(OTHER_BED).useWithoutItem(nether,p,new BlockHitResult(Vec3.atCenterOf(OTHER_BED),Direction.UP,OTHER_BED,false));ok(p.isSleeping(),"real connected client sleeps in Nether bed");});
   if(s==16)server(p->{p.stopSleepInBed(true,true);p.hurt(p.damageSources().genericKill(),Float.MAX_VALUE);ok(p.isDeadOrDying(),"real player death after otherworld spawn set");});
   if(s==17&&m.player!=null){m.player.respawn();m.setScreen(null);}
   if(s==18)server(p->{ok(p.isAlive()&&p.serverLevel().dimension().equals(Level.NETHER),"real death and client respawn returns to Nether");ok(p.position().distanceTo(Vec3.atCenterOf(OTHER_BED))<6,"real player respawns beside bed");camera(p,new Vec3(4,103,4),new Vec3(.5,100.5,0));});
   if(s==19)server(p->{var world=p.server.getLevel(Level.OVERWORLD);p.teleportTo(world,215,-56,35,180,30);p.gameMode.changeGameModeForPlayer(GameType.CREATIVE);camera(p,new Vec3(216,-48,38),new Vec3(217,-60,21));});
   if(s==20)server(p->{var l=p.serverLevel();var reg=l.registryAccess().registryOrThrow(Registries.BIOME);var chunk=l.getChunk(13,1);oldCells.clear();for(int x=52;x<=55;x++)for(int y=-16;y<=-9;y++)for(int z=4;z<=7;z++)oldCells.put(new BlockPos(x*4,y*4,z*4),reg.getKey(chunk.getNoiseBiome(x,y,z).value()).toString());oldBiome=reg.getKey(l.getBiome(BIOME).value()).toString();p.server.getCommands().performPrefixedCommand(p.server.createCommandSourceStack().withLevel(l).withSuppressedOutput().withCallback((success,count)->{System.out.println("R10_BIOME_COMMAND success="+success+" count="+count);ok(success&&count>0,"fillbiome command changes existing quart cells");}),"fillbiome 208 -64 16 223 -33 31 minecraft:cherry_grove");ok(chunk.getNoiseBiome(54,-15,6).is(net.minecraft.world.level.biome.Biomes.CHERRY_GROVE),"raw server biome cell changes immediately");ok(l.getBiome(BIOME).is(net.minecraft.world.level.biome.Biomes.CHERRY_GROVE),"server biome changed without world recreation");biomeChanged=true;});
   if(s==22)server(p->{ok(biomeChanged,"biome probe completed");var l=p.serverLevel();for(var cell:oldCells.entrySet()){var q=cell.getKey();p.server.getCommands().performPrefixedCommand(p.server.createCommandSourceStack().withLevel(l).withSuppressedOutput(),"fillbiome "+q.getX()+" "+q.getY()+" "+q.getZ()+" "+(q.getX()+3)+" "+(q.getY()+3)+" "+(q.getZ()+3)+" "+cell.getValue());}var reg=l.registryAccess().registryOrThrow(Registries.BIOME);for(var cell:oldCells.entrySet()){var q=cell.getKey();ok(reg.getKey(l.getChunk(13,1).getNoiseBiome(q.getX()>>2,q.getY()>>2,q.getZ()>>2).value()).toString().equals(cell.getValue()),"biome experiment restores original quart cell "+q);} });
  }
  if(s==21&&t==30){ok(m.level.dimension().equals(Level.OVERWORLD),"client returned to overworld");ok(m.level.getBiome(BIOME).is(net.minecraft.world.level.biome.Biomes.CHERRY_GROVE),"client receives live biome update in loaded chunk");}
  if(s==13&&t==30)org.lwjgl.glfw.GLFW.glfwSetCursorPos(m.getWindow().getWindow(),468,366);
  if(t==45){Screenshot.grab(OUT.toFile(),"r10-"+s+".png",m.getMainRenderTarget(),c->{});System.out.println("R10_CAPTURE "+s);}frame++;
 }
